import {
  Chart as ChartJS,
  LineElement,
  CategoryScale,
  LinearScale,
  PointElement,
  Tooltip,
} from "chart.js";
import { Line } from "react-chartjs-2";

ChartJS.register(LineElement, CategoryScale, LinearScale, PointElement, Tooltip);

// ✨ Glow Plugin
const glowPlugin = {
  id: "glowLine",
  beforeDatasetDraw(chart) {
    const { ctx } = chart;

    ctx.save();
    ctx.shadowColor = "rgba(59,130,246,0.6)"; // blue glow
    ctx.shadowBlur = 15;
    ctx.shadowOffsetX = 0;
    ctx.shadowOffsetY = 0;
  },
  afterDatasetDraw(chart) {
    chart.ctx.restore();
  },
};

export default function ProgressChart({ completedDays }) {
  const labels = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];

  const data = {
    labels,
    datasets: [
      {
        label: "Tasks",
        data: labels.map((_, i) =>
          completedDays.includes(i + 1) ? 4 : 0
        ),
        borderColor: "#3b82f6",
        borderWidth: 3,
        tension: 0.4,
        pointRadius: 4,
        pointBackgroundColor: "#22d3ee",
        fill: false,
      },
    ],
  };

  const options = {
    responsive: true,
    plugins: {
      legend: { display: false },
    },
    animation: {
      duration: 1500,
      easing: "easeOutQuart",
    },
    scales: {
      x: {
        grid: { display: false },
        ticks: { color: "#94a3b8" },
      },
      y: {
        beginAtZero: true,
        grid: { display: false },
        ticks: { color: "#94a3b8" },
      },
    },
  };

  return <Line data={data} options={options} plugins={[glowPlugin]} />;
}
